export function CourseAssignmentPanel({
  courseId,
  lessonId,
}: {
  courseId: string;
  lessonId: string;
}) {
  const t = useTranslations("studentWorkspace");
  const locale = useLocale();
  const client = useQueryClient();
  const [active, setActive] = useState<{
    assignmentId: string;
    submissionId: string;
  }>();
  const [comment, setComment] = useState("");
  const [files, setFiles] = useState<File[]>([]);
  const assignments = useQuery({
    queryKey: ["student-course-assignments", courseId],
    queryFn: () =>
      api<StudentCourseAssignment[]>(
        `/student/courses/${courseId}/assignments`,
      ),
  });
  const mine = useQuery({
    queryKey: ["student-course-assignment-submissions"],
    queryFn: () =>
      api<StudentCourseAssignmentSubmission[]>("/student/assignments/mine"),
  });
  const refresh = () => {
    client.invalidateQueries({
      queryKey: ["student-course-assignments", courseId],
    });
    client.invalidateQueries({
      queryKey: ["student-course-assignment-submissions"],
    });
  };
  const start = useMutation({
    mutationFn: (assignmentId: string) =>
      api<{ submissionId: string }>(
        `/student/assignments/${assignmentId}/submissions`,
        { method: "POST", body: JSON.stringify({ comment }) },
      ),
    onSuccess: (response, assignmentId) => {
      setActive({ assignmentId, submissionId: response.submissionId });
      setFiles([]);
      refresh();
    },
  });
  const upload = useMutation({
    mutationFn: async () => {
      if (!active)
        throw new Error("Start the submission before uploading files.");
      for (const file of files) {
        const body = new FormData();
        body.set("file", file);
        await api(
          `/student/assignments/submissions/${active.submissionId}/files`,
          {
            method: "POST",
            body,
          },
        );
      }
    },
    onSuccess: () => {
      setFiles([]);
      refresh();
    },
  });
  const submit = useMutation({
    mutationFn: () => {
      if (!active) throw new Error("Start the submission before submitting.");
      return api(
        `/student/assignments/submissions/${active.submissionId}/submit`,
        {
          method: "POST",
        },
      );
    },
    onSuccess: () => {
      setActive(undefined);
      setFiles([]);
      setComment("");
      refresh();
    },
  });
  const visible = (assignments.data ?? []).filter(
    (assignment) => !assignment.lessonId || assignment.lessonId === lessonId,
  );
  if (assignments.isPending || !visible.length) return null;
  return (
    <section className="mt-6 grid gap-4 rounded-2xl border border-primary/25 bg-primary/5 p-4">
      <div>
        <h2 className="flex items-center gap-2 text-lg font-black">
          <ClipboardCheck
            size={19}
            className="text-primary"
            aria-hidden="true"
          />
          {t("coursework.title")}
        </h2>
        <p className="mt-1 text-sm text-muted">{t("coursework.description")}</p>
      </div>
      {visible.map((assignment) => {
        const submission = mine.data?.find(
          (item) => item.assignmentId === assignment.id,
        );
        const activeHere = active?.assignmentId === assignment.id;
        const opensInFuture = Boolean(
          assignment.availableFromUtc &&
          new Date(assignment.availableFromUtc) > new Date(),
        );
        const deadlinePassed = Boolean(
          assignment.effectiveDueAtUtc &&
          new Date(assignment.effectiveDueAtUtc) < new Date(),
        );
        return (
          <article
            key={assignment.id}
            className="rounded-xl border border-border bg-surface-solid/55 p-4"
          >
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <h3 className="font-black">
                  {locale === "ar"
                    ? assignment.arabicTitle
                    : assignment.englishTitle}
                </h3>
                <p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted">
                  {locale === "ar"
                    ? assignment.arabicInstructions
                    : assignment.englishInstructions}
                </p>
                {assignment.effectiveDueAtUtc ? (
                  <p className="mt-2 text-xs text-muted">
                    {t("coursework.due")}{" "}
                    {formatLocalizedDateTime(
                      assignment.effectiveDueAtUtc,
                      locale,
                    )}
                  </p>
                ) : null}
                {assignment.hasDeadlineExtension ? (
                  <p className="mt-1 text-xs font-bold text-primary">
                    {t("coursework.deadlineAdjustment")}
                  </p>
                ) : null}
                {assignment.availableFromUtc ? (
                  <p className="mt-2 text-xs text-muted">
                    {t("coursework.opens")}{" "}
                    {formatLocalizedDateTime(
                      assignment.availableFromUtc,
                      locale,
                    )}
                  </p>
                ) : null}
                <p className="mt-2 text-xs text-muted">
                  {t("coursework.files")}{" "}
                  {assignment.allowedFileExtensions.join(", ").toUpperCase()} ·{" "}
                  {Math.round(assignment.maxFileSizeBytes / 1024 / 1024)}MB
                </p>
                {assignment.resources.length ? (
                  <div className="mt-3 flex flex-wrap gap-2">
                    {assignment.resources.map((resource) => (
                      <a
                        key={resource.id}
                        href={`/api/v1/assignments/${assignment.id}/resources/${resource.id}`}
                        className="focus-ring rounded-lg border border-primary/35 px-2.5 py-2 text-xs font-bold text-primary"
                      >
                        <FileBadge
                          size={14}
                          className="me-1 inline"
                          aria-hidden="true"
                        />
                        {resource.displayName}
                      </a>
                    ))}
                  </div>
                ) : null}
              </div>
              {submission?.calculatedGrade ? (
                <span className="rounded-full bg-primary/15 px-3 py-1 text-sm font-black text-primary">
                  {submission.calculatedGrade}
                </span>
              ) : submission ? (
                <span className="rounded-full border border-border px-3 py-1 text-xs font-bold text-muted">
                  {submission.status}
                </span>
              ) : null}
            </div>
            <ul className="mt-3 grid gap-1 text-sm">
              {assignment.criteria.map((criterion) => (
                <li
                  key={criterion.id}
                  className="rounded-lg border border-border/70 p-2"
                >
                  <strong className="text-primary">{criterion.code}</strong> —{" "}
                  {locale === "ar"
                    ? criterion.arabicDescription
                    : criterion.englishDescription}
                </li>
              ))}
            </ul>
            {submission?.results.length ? (
              <div className="mt-3 grid gap-2 border-t border-border pt-3">
                <p className="font-bold">{t("coursework.criterionResult")}</p>
                {submission.results.map((result) => (
                  <p key={result.code} className="text-sm text-muted">
                    <strong className="text-primary">{result.code}</strong> —{" "}
                    {result.achievement}
                    {result.feedback ? ` · ${result.feedback}` : ""}
                  </p>
                ))}
              </div>
            ) : null}
            {submission?.feedback.length ? (
              <div className="mt-3 grid gap-2 border-t border-border pt-3">
                {submission.feedback.map((item) => (
                  <p
                    key={`${item.createdAtUtc}-${item.body}`}
                    className="rounded-lg bg-black/5 p-2.5 text-sm text-muted"
                  >
                    {item.requestsResubmission ? "↻ " : ""}
                    {item.body}
                  </p>
                ))}
              </div>
            ) : null}
            {submission?.versions.length ? (
              <div className="mt-3 flex flex-wrap gap-2">
                {submission.versions
                  .flatMap((version) => version.files)
                  .map((file) => (
                    <a
                      key={file.id}
                      href={`/api/v1/assignments/submissions/${submission.id}/files/${file.id}`}
                      className="focus-ring rounded-lg border border-primary/35 px-2.5 py-2 text-xs font-bold text-primary"
                    >
                      <FileBadge
                        size={14}
                        className="me-1 inline"
                        aria-hidden="true"
                      />
                      {file.originalFileName}
                    </a>
                  ))}
              </div>
            ) : null}
            {submission?.status !== "Graded" &&
            submission?.status !== "Finalized" ? (
              <div className="mt-4 border-t border-border pt-4">
                {!activeHere ? (
                  <button
                    type="button"
                    onClick={() => start.mutate(assignment.id)}
                    disabled={
                      start.isPending ||
                      opensInFuture ||
                      deadlinePassed ||
                      (submission?.status === "NeedsRevision" &&
                        !assignment.allowResubmission)
                    }
                    className="focus-ring rounded-xl bg-primary px-4 py-2.5 text-sm font-black text-slate-950 disabled:opacity-50"
                  >
                    {deadlinePassed
                      ? t("coursework.actions.deadlinePassed")
                      : opensInFuture
                        ? t("coursework.actions.notOpenYet")
                        : submission?.status === "NeedsRevision" &&
                            !assignment.allowResubmission
                          ? t("coursework.actions.resubmissionUnavailable")
                          : submission?.status === "NeedsRevision"
                            ? t("coursework.actions.startResubmission")
                            : submission?.status === "Draft"
                              ? t("coursework.actions.continueDraft")
                              : t("coursework.actions.startSubmission")}
                  </button>
                ) : (
                  <div className="grid gap-3">
                    <textarea
                      value={comment}
                      onChange={(event) => setComment(event.target.value)}
                      maxLength={4000}
                      placeholder={t("coursework.submission.notePlaceholder")}
                      className="min-h-20 rounded-xl border border-border bg-transparent p-2.5 text-sm"
                    />
                    <FilePicker
                      label={t("coursework.submission.workFiles")}
                      files={files}
                      onFilesChange={setFiles}
                      locale={locale}
                      multiple
                      accept={assignment.allowedFileExtensions.join(",")}
                      maxFileBytes={assignment.maxFileSizeBytes}
                      chooseLabel={t("coursework.submission.chooseFiles")}
                      helpText={t("coursework.submission.fileHelp", {
                        size: String(
                          Math.round(assignment.maxFileSizeBytes / 1024 / 1024),
                        ),
                      })}
                    />
                    <div className="flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => start.mutate(assignment.id)}
                        disabled={start.isPending || deadlinePassed}
                        className="focus-ring rounded-xl border border-border px-4 py-2.5 text-sm font-bold text-muted disabled:opacity-50"
                      >
                        {t("coursework.submission.saveNote")}
                      </button>
                      <button
                        type="button"
                        onClick={() => upload.mutate()}
                        disabled={
                          !files.length || upload.isPending || deadlinePassed
                        }
                        className="focus-ring rounded-xl border border-primary/40 px-4 py-2.5 text-sm font-bold text-primary disabled:opacity-50"
                      >
                        {t("coursework.submission.uploadFiles")}
                      </button>
                      <button
                        type="button"
                        onClick={() => submit.mutate()}
                        disabled={submit.isPending || deadlinePassed}
                        className="focus-ring rounded-xl bg-primary px-4 py-2.5 text-sm font-black text-slate-950 disabled:opacity-50"
                      >
                        {t("coursework.submission.submit")}
                      </button>
                    </div>
                    {upload.isError || submit.isError ? (
                      <p role="alert" className="text-sm text-red-400">
                        {(upload.error ?? submit.error) instanceof Error
                          ? (upload.error ?? submit.error)?.message
                          : t("coursework.errors.action")}
                      </p>
                    ) : null}
                  </div>
                )}
              </div>
            ) : null}
          </article>
        );
      })}
      {start.isError ? (
        <p role="alert" className="text-sm text-red-400">
          {start.error instanceof Error
            ? start.error.message
            : t("coursework.errors.start")}
        </p>
      ) : null}
      {assignments.isError || mine.isError ? (
        <p role="alert" className="text-sm text-red-400">
          {t("coursework.errors.load")}
        </p>
      ) : null}
    </section>
  );
}

sources.resit:
export function StudentResitDetail({ evaluationId }: { evaluationId: string }) {
  const locale = useLocale();
  const t = useTranslations("studentWorkspace.resitWorkflow.detail");
  const router = useRouter();
  const client = useQueryClient();
  const [files, setFiles] = useState<File[]>([]);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [confirmOriginality, setConfirmOriginality] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState("Card");
  const [paymentSession, setPaymentSession] = useState<{
    paymentId: string;
    provider: string;
    redirectUrl: string | null;
    total: number;
    currency: string;
  } | null>(null);
  const checkoutKey = useRef<string | null>(null);
  const detail = useQuery({
    queryKey: ["evaluations", "detail", evaluationId],
    queryFn: () => api<Detail>(`/evaluations/${evaluationId}`),
  });
  const refresh = () =>
    client.invalidateQueries({
      queryKey: ["evaluations", "detail", evaluationId],
    });
  const upload = useMutation({
    mutationFn: async () => {
      for (const file of files) {
        const body = new FormData();
        body.set("file", file);
        await api(`/evaluations/${evaluationId}/files`, {
          method: "POST",
          body,
        });
      }
    },
    onSuccess: async () => {
      setFiles([]);
      await refresh();
    },
  });
  const saveEvidence = useMutation({
    mutationFn: ({
      criterionCode,
      narrative,
    }: {
      criterionCode: string;
      narrative: string;
    }) =>
      api(`/evaluations/${evaluationId}/evidence`, {
        method: "POST",
        body: JSON.stringify({ criterionCode, narrative }),
      }),
    onSuccess: refresh,
  });
  const declare = useMutation({
    mutationFn: () =>
      api(`/evaluations/${evaluationId}/authenticity-declaration`, {
        method: "POST",
      }),
    onSuccess: async () => {
      setConfirmOriginality(false);
      await refresh();
    },
  });
  const checkout = useMutation({
    mutationFn: async () => {
      checkoutKey.current ??= crypto.randomUUID();
      const result = await api<{
        includedCreditApplied: boolean;
        paymentId: string;
        provider: string;
        redirectUrl: string | null;
        total: number;
        currency: string;
      }>(`/evaluations/${evaluationId}/checkout`, {
        method: "POST",
        headers: { "Idempotency-Key": checkoutKey.current },
        body: JSON.stringify({ paymentMethod, expectIncludedCredit: false }),
      });
      if (result.includedCreditApplied)
        throw new Error("RESIT_INCLUDED_CREDIT_INVARIANT_VIOLATION");
      return result;
    },
    onSuccess: async (result) => {
      checkoutKey.current = null;
      if (result.redirectUrl) {
        window.location.assign(result.redirectUrl);
        return;
      }
      setPaymentSession(result);
      await refresh();
    },
  });
  const confirmDevelopmentPayment = useMutation({
    mutationFn: async () => {
      if (!paymentSession?.provider.startsWith("Fake"))
        throw new Error("No development test payment is available.");
      await api("/payments/fake/confirm", {
        method: "POST",
        body: JSON.stringify({
          paymentId: paymentSession.paymentId,
          providerEventId: `resit_test_${crypto.randomUUID()}`,
        }),
      });
    },
    onSuccess: async () => {
      await client.invalidateQueries({ queryKey: ["evaluations"] });
      await client.invalidateQueries({
        queryKey: ["student", "resit-authorizations"],
      });
      router.push(`/${locale}/student/evaluations`);
    },
  });
  const data = detail.data;
  return (
    <section className="shell grid min-w-0 gap-4 py-10">
      <Link
        className="focus-ring w-fit font-semibold text-primary underline"
        href={`/${locale}/student/evaluations`}
      >
        {t("back")}
      </Link>
      {detail.isPending ? <p role="status">{t("loading")}</p> : null}
      {detail.isError || (data && !data.isResit) ? (
        <p role="alert">{t("unavailable")}</p>
      ) : null}
      {data?.isResit ? (
        <>
          <header className="card grid gap-2 p-5">
            <h1 className="text-2xl font-black">{t("header.title")}</h1>
            <AcademicContext academic={data.academic} locale={locale} />
            <p>
              {t("header.status")}: {data.status}
            </p>
            {data.resitOfEvaluationRequestId ? (
              <p className="text-sm">
                {t("header.originalRequest")}:{" "}
                {data.resitOfEvaluationRequestId.slice(0, 8)}
              </p>
            ) : null}
          </header>
          {data.status === "Draft" ? (
            <div className="card grid gap-5 p-5">
              <h2 className="text-xl font-black">{t("draft.title")}</h2>
              <FilePicker
                label={t("draft.files.label")}
                files={files}
                onFilesChange={setFiles}
                locale={locale}
                accept=".pdf,.docx,.xlsx,.txt,.jpg,.jpeg,.png,.webp"
                multiple
                maxFileBytes={100 * 1024 * 1024}
                chooseLabel={t("draft.files.choose")}
              />
              <button
                type="button"
                className="focus-ring w-fit rounded-xl bg-primary px-4 py-2 font-bold text-white disabled:opacity-50"
                disabled={!files.length || upload.isPending}
                onClick={() => upload.mutate()}
              >
                {t("draft.files.upload")}
              </button>
              {upload.isError ? (
                <p role="alert" className="text-red-500">
                  {t("draft.files.uploadError")}
                </p>
              ) : null}
              {upload.isSuccess ? (
                <p role="status" className="text-sm text-primary">
                  {t("draft.files.saved")}
                </p>
              ) : null}
              <div className="grid gap-2">
                <h3 className="font-bold">{t("draft.files.savedTitle")}</h3>
                {data.files.length ? (
                  <ul className="grid gap-1 text-sm">
                    {data.files.map((file) => (
                      <li key={file.id} className="break-words">
                        {file.originalFileName} · {file.scanStatus}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-sm text-muted">{t("draft.files.empty")}</p>
                )}
              </div>
              <div className="grid gap-3">
                <h3 className="font-bold">{t("draft.evidence.title")}</h3>
                {data.criteria.map((criterion) => {
                  const saved =
                    data.evidence.find(
                      (item) => item.criterionCode === criterion,
                    )?.narrative ?? "";
                  return (
                    <div key={criterion} className="grid gap-2">
                      <label className="grid gap-1 text-sm font-semibold">
                        {t("draft.evidence.label", { criterion })}
                        <textarea
                          key={`${criterion}:${saved}`}
                          className="min-h-24 min-w-0 rounded-xl border border-border bg-transparent p-3"
                          maxLength={4000}
                          defaultValue={saved}
                          onChange={(event) =>
                            setDrafts((current) => ({
                              ...current,
                              [criterion]: event.target.value,
                            }))
                          }
                        />
                      </label>
                      <button
                        type="button"
                        className="focus-ring w-fit rounded-lg border px-3 py-2 font-semibold disabled:opacity-50"
                        disabled={
                          saveEvidence.isPending ||
                          !(drafts[criterion] ?? saved).trim()
                        }
                        onClick={() =>
                          saveEvidence.mutate({
                            criterionCode: criterion,
                            narrative: (drafts[criterion] ?? saved).trim(),
                          })
                        }
                      >
                        {t("draft.evidence.save")}
                      </button>
                    </div>
                  );
                })}
                {saveEvidence.isError ? (
                  <p role="alert" className="text-red-500">
                    {t("draft.evidence.saveError")}
                  </p>
                ) : null}
                {saveEvidence.isSuccess ? (
                  <p role="status" className="text-sm text-primary">
                    {t("draft.evidence.saved")}
                  </p>
                ) : null}
              </div>
              {data.hasAuthenticityDeclaration ? (
                <p role="status" className="font-semibold text-primary">
                  {t("draft.authenticity.confirmed")}
                </p>
              ) : (
                <>
                  <label className="flex items-start gap-2 text-sm">
                    <input
                      type="checkbox"
                      className="focus-ring mt-1"
                      checked={confirmOriginality}
                      onChange={(event) =>
                        setConfirmOriginality(event.target.checked)
                      }
                    />
                    {t("draft.authenticity.declaration")}
                  </label>
                  <button
                    type="button"
                    className="focus-ring w-fit rounded-lg border px-3 py-2 font-semibold disabled:opacity-50"
                    disabled={!confirmOriginality || declare.isPending}
                    onClick={() => declare.mutate()}
                  >
                    {t("draft.authenticity.confirm")}
                  </button>
                  {declare.isError ? (
                    <p role="alert" className="text-red-500">
                      {t("draft.authenticity.error")}
                    </p>
                  ) : null}
                </>
              )}
              {data.files.some((file) => file.scanStatus === "Clean") &&
              data.hasAuthenticityDeclaration ? (
                <p role="status" className="font-semibold">
                  {t("draft.preparationComplete")}
                </p>
              ) : null}
              <div className="grid gap-3 rounded-xl border border-primary/30 bg-primary/5 p-4 text-sm">
                <p className="font-black">{t("payment.title")}</p>
                <p>
                  {t("payment.price", {
                    price: formatLocalizedCurrency(
                      data.price,
                      data.currency,
                      locale,
                    ),
                  })}
                </p>
                <label className="grid gap-1 font-semibold">
                  {t("payment.method")}
                  <select
                    value={paymentMethod}
                    onChange={(event) => setPaymentMethod(event.target.value)}
                    className="rounded-lg border bg-transparent p-3"
                  >
                    <option value="Card">{t("payment.methods.card")}</option>
                    <option value="BankTransfer">
                      {t("payment.methods.bankTransfer")}
                    </option>
                    <option value="EWallet">
                      {t("payment.methods.eWallet")}
                    </option>
                  </select>
                </label>
                <button
                  type="button"
                  className="focus-ring w-fit rounded-xl bg-primary px-4 py-2 font-bold text-white disabled:opacity-50"
                  disabled={
                    checkout.isPending ||
                    !data.files.some((file) => file.scanStatus === "Clean") ||
                    !data.hasAuthenticityDeclaration
                  }
                  onClick={() => checkout.mutate()}
                >
                  {checkout.isPending ? "…" : t("payment.continue")}
                </button>
                {checkout.isError ? (
                  <p role="alert" className="text-red-500">
                    {checkout.error.message ===
                    "RESIT_INCLUDED_CREDIT_INVARIANT_VIOLATION"
                      ? t("payment.stateConflict")
                      : t("payment.startError")}
                  </p>
                ) : null}
              </div>
            </div>
          ) : data.status === "PendingPayment" ? (
            <div className="card grid gap-3 p-5" aria-live="polite">
              <h2 className="text-xl font-black">
                {t("payment.pendingTitle")}
              </h2>
              {paymentSession?.provider.startsWith("Fake") ? (
                <>
                  <p>{t("payment.developmentDescription")}</p>
                  <button
                    type="button"
                    className="focus-ring w-fit rounded-lg border border-primary px-3 py-2 font-black text-primary disabled:opacity-50"
                    disabled={confirmDevelopmentPayment.isPending}
                    onClick={() => confirmDevelopmentPayment.mutate()}
                  >
                    {confirmDevelopmentPayment.isPending
                      ? "…"
                      : t("payment.completeTest")}
                  </button>
                  {confirmDevelopmentPayment.isError ? (
                    <p role="alert">{t("payment.confirmTestError")}</p>
                  ) : null}
                </>
              ) : (
                <p>{t("payment.pendingHelp")}</p>
              )}
            </div>
          ) : data.status === "Completed" ? (
            <div className="card grid gap-3 p-5">
              <h2 className="text-xl font-black">{t("completed.title")}</h2>
              <p className="text-2xl font-black">
                {data.calculatedGrade ?? "—"}
              </p>
              {data.sectionResults.map((result) => (
                <p key={result.section}>
                  {result.section}: {result.grade}
                </p>
              ))}
              {data.results.map((result) => (
                <p key={result.criterionCode}>
                  {result.criterionCode}: {result.achievement}
                  {result.comment ? ` · ${result.comment}` : ""}
                </p>
              ))}
              {data.feedback.map((item) => (
                <p key={item.createdAtUtc}>{item.body}</p>
              ))}
              <p className="text-xs text-muted">{t("completed.disclaimer")}</p>
            </div>
          ) : (
            <p className="card p-5 text-sm text-muted">{t("awaitingResult")}</p>
          )}
        </>
      ) : null}
    </section>
  );
}
